const markExpiredIngressUsageRunIncomplete = `-- name: MarkExpiredIngressUsageRunIncomplete :exec
UPDATE control.ingress_usage_runs
SET ended_at = COALESCE(ended_at, $1),
    incomplete_from = observed_through,
    incomplete_until = $1
WHERE ingress_id = $2
  AND ingress_run_id = $3
  AND ended_at IS NULL
`

type MarkExpiredIngressUsageRunIncompleteParams struct {
	EndedAt      pgtype.Timestamptz
	IngressID    string
	IngressRunID string
}

func (q *Queries) MarkExpiredIngressUsageRunIncomplete(ctx context.Context, arg MarkExpiredIngressUsageRunIncompleteParams) error {
	_, err := q.db.Exec(ctx, markExpiredIngressUsageRunIncomplete, arg.EndedAt, arg.IngressID, arg.IngressRunID)
	return err
}

const markExpiredIngressUsageRunsIncomplete = `-- name: MarkExpiredIngressUsageRunsIncomplete :many
UPDATE control.ingress_usage_runs
SET ended_at = lease_expires_at,
    incomplete_from = observed_through,
    incomplete_until = lease_expires_at
WHERE ended_at IS NULL
  AND lease_expires_at <= $1
RETURNING ingress_id, ingress_run_id, ingress_lease_revision, started_at, lease_expires_at, last_reported_at, observed_through, ended_at, coverage_complete, incomplete_from, incomplete_until
`

func (q *Queries) MarkExpiredIngressUsageRunsIncomplete(ctx context.Context, now pgtype.Timestamptz) ([]ControlIngressUsageRun, error) {
	rows, err := q.db.Query(ctx, markExpiredIngressUsageRunsIncomplete, now)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ControlIngressUsageRun
	for rows.Next() {
		var i ControlIngressUsageRun
		if err := rows.Scan(
			&i.IngressID,
			&i.IngressRunID,
			&i.IngressLeaseRevision,
			&i.StartedAt,
			&i.LeaseExpiresAt,
			&i.LastReportedAt,
			&i.ObservedThrough,
			&i.EndedAt,
			&i.CoverageComplete,
			&i.IncompleteFrom,
			&i.IncompleteUntil,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const markIngressUsageRunReported = `-- name: MarkIngressUsageRunReported :one
UPDATE control.ingress_usage_runs AS runs
SET last_reported_at = GREATEST(COALESCE(runs.last_reported_at, $1), $1),
    observed_through = GREATEST(runs.observed_through, COALESCE($2::timestamptz, runs.observed_through)),
    ended_at = CASE WHEN $3::boolean THEN $2::timestamptz ELSE runs.ended_at END,
    coverage_complete = runs.coverage_complete OR $3::boolean
WHERE runs.ingress_id = $4
  AND runs.ingress_run_id = $5
  AND runs.ingress_lease_revision = $6
  AND ($2::timestamptz IS NULL OR runs.observed_through <= $2::timestamptz)
  AND (
      NOT runs.coverage_complete
      OR (
          $3::boolean
          AND runs.observed_through = $2::timestamptz
      )
  )
RETURNING ingress_id, ingress_run_id, ingress_lease_revision, started_at, lease_expires_at, last_reported_at, observed_through, ended_at, coverage_complete, incomplete_from, incomplete_until
`

type MarkIngressUsageRunReportedParams struct {
	ReportedAt           pgtype.Timestamptz
	ObservedThrough      pgtype.Timestamptz
	Complete             bool
	IngressID            string
	IngressRunID         string
	IngressLeaseRevision int64
}

func (q *Queries) MarkIngressUsageRunReported(ctx context.Context, arg MarkIngressUsageRunReportedParams) (ControlIngressUsageRun, error) {
	row := q.db.QueryRow(ctx, markIngressUsageRunReported,
		arg.ReportedAt,
		arg.ObservedThrough,
		arg.Complete,
		arg.IngressID,
		arg.IngressRunID,
		arg.IngressLeaseRevision,
	)
	var i ControlIngressUsageRun
	err := row.Scan(
		&i.IngressID,
		&i.IngressRunID,
		&i.IngressLeaseRevision,
		&i.StartedAt,
		&i.LeaseExpiresAt,
		&i.LastReportedAt,
		&i.ObservedThrough,
		&i.EndedAt,
		&i.CoverageComplete,
		&i.IncompleteFrom,
		&i.IncompleteUntil,
	)
	return i, err
}

